define(["core/str","core/notification"],function(Str,Notification){const SELECTORS={cancel:'[data-action="cancel-goal"]'};const confirmCancel=function(event){const link=event.currentTarget;event.preventDefault();Promise.all([Str.get_string("cancelconfirmtitle","local_personalgoals"),Str.get_string("cancelconfirmbody","local_personalgoals"),Str.get_string("cancelgoal","local_personalgoals"),Str.get_string("cancel")]).then(function(strings){Notification.confirm(strings[0],strings[1],strings[2],strings[3],function(){window.location.href=link.href});return true}).catch(Notification.exception)};const init=function(){document.querySelectorAll(SELECTORS.cancel).forEach(function(link){link.addEventListener("click",confirmCancel)})};return{init:init}});